-- KrakenAnimate.server.lua (generated by the Kraken viewer)
-- Put this Script inside the imported Kraken Model (keep the exported part names).
-- It rigs Motor6Ds at runtime, then plays "Idle" / "Swim" + eye glow + ink trail.
--   model:SetAttribute("Anim", "Swim")  -- or "Idle"
-- Move the creature by moving the created "KrakenRoot" part (it becomes PrimaryPart).
local RunService = game:GetService("RunService")
local model = script.Parent
local function find(n) return model:FindFirstChild(n, true) end

local body = find("Body") :: BasePart
assert(body, "KrakenAnimate: 'Body' part not found")
local SCALE = body.Size.Magnitude / 5.9466
local cf0 = body.CFrame
local rot0 = cf0 - cf0.Position
local function W(v: Vector3) return cf0:PointToWorldSpace(v * SCALE) end

local SWIM_PERIOD = 1.4
local ARMS = {
	{ i = 1, hunter = false, ph = 1.794, sp = 0.851, rest = { 0.7, 0.15, 0.3, 0.55 }, axis = Vector3.new(0.924, 0.000, -0.383),
	  joints = { Vector3.new(0.188, -1.618, 0.926), Vector3.new(0.496, -2.574, 1.670), Vector3.new(0.812, -3.300, 2.434), Vector3.new(1.161, -3.709, 3.277) }, tipOff = Vector3.new(0.182, 0.062, 0.465) },
	{ i = 2, hunter = true, ph = 0.738, sp = 0.979, rest = { 1.2, 0.55, 0.6, 0.85 }, axis = Vector3.new(0.383, 0.000, -0.924),
	  joints = { Vector3.new(0.485, -1.699, 0.629), Vector3.new(1.691, -2.207, 1.128), Vector3.new(2.873, -1.975, 1.618), Vector3.new(3.661, -1.132, 1.944) }, tipOff = Vector3.new(-0.037, 0.620, -0.014) },
	{ i = 3, hunter = false, ph = 1.111, sp = 1.156, rest = { 0.7, 0.15, 0.3, 0.55 }, axis = Vector3.new(-0.383, 0.000, -0.924),
	  joints = { Vector3.new(0.485, -1.814, 0.208), Vector3.new(1.229, -2.770, -0.100), Vector3.new(1.993, -3.496, -0.417), Vector3.new(2.836, -3.905, -0.766) }, tipOff = Vector3.new(0.465, 0.062, -0.183) },
	{ i = 4, hunter = false, ph = 0.248, sp = 1.158, rest = { 0.7, 0.15, 0.3, 0.55 }, axis = Vector3.new(-0.924, 0.000, -0.383),
	  joints = { Vector3.new(0.188, -1.895, -0.090), Vector3.new(0.496, -2.851, -0.834), Vector3.new(0.812, -3.577, -1.597), Vector3.new(1.161, -3.986, -2.441) }, tipOff = Vector3.new(0.187, 0.069, -0.463) },
	{ i = 5, hunter = false, ph = 2.745, sp = 0.912, rest = { 0.7, 0.15, 0.3, 0.55 }, axis = Vector3.new(-0.924, 0.000, 0.383),
	  joints = { Vector3.new(-0.233, -1.895, -0.090), Vector3.new(-0.541, -2.851, -0.834), Vector3.new(-0.858, -3.577, -1.597), Vector3.new(-1.207, -3.986, -2.441) }, tipOff = Vector3.new(-0.184, 0.062, -0.465) },
	{ i = 6, hunter = false, ph = 0.803, sp = 1.171, rest = { 0.7, 0.15, 0.3, 0.55 }, axis = Vector3.new(-0.383, 0.000, 0.924),
	  joints = { Vector3.new(-0.531, -1.814, 0.208), Vector3.new(-1.275, -2.770, -0.100), Vector3.new(-2.038, -3.496, -0.417), Vector3.new(-2.882, -3.905, -0.766) }, tipOff = Vector3.new(-0.463, 0.070, -0.186) },
	{ i = 7, hunter = true, ph = 2.804, sp = 0.932, rest = { 1.2, 0.55, 0.6, 0.85 }, axis = Vector3.new(0.383, 0.000, 0.924),
	  joints = { Vector3.new(-0.531, -1.699, 0.629), Vector3.new(-1.736, -2.207, 1.128), Vector3.new(-2.918, -1.975, 1.618), Vector3.new(-3.707, -1.132, 1.944) }, tipOff = Vector3.new(0.027, 0.621, -0.004) },
	{ i = 8, hunter = false, ph = 5.591, sp = 1.057, rest = { 0.7, 0.15, 0.3, 0.55 }, axis = Vector3.new(0.924, 0.000, 0.383),
	  joints = { Vector3.new(-0.233, -1.618, 0.926), Vector3.new(-0.541, -2.574, 1.670), Vector3.new(-0.858, -3.300, 2.434), Vector3.new(-1.207, -3.709, 3.277) }, tipOff = Vector3.new(-0.186, 0.070, 0.463) },
}

-- Root + rig (built from the rest pose)
local root = Instance.new("Part")
root.Name = "KrakenRoot"; root.Size = Vector3.one * 0.5; root.Transparency = 1
root.Anchored = true; root.CanCollide = false; root.CanQuery = false; root.CanTouch = false
root.CFrame = CFrame.new(W(Vector3.new(-0.023, -1.257, 0.418))) * rot0
root.Parent = model; model.PrimaryPart = root

local function motor(p0: BasePart, p1: BasePart, jointWorld: CFrame)
	local m = Instance.new("Motor6D")
	m.Part0 = p0; m.Part1 = p1
	m.C0 = p0.CFrame:Inverse() * jointWorld
	m.C1 = p1.CFrame:Inverse() * jointWorld
	m.Parent = p1
	return m
end
local bodyMotor = motor(root, body, root.CFrame)
local bodyC0 = bodyMotor.C0
for _, n in { "Eyes", "Pupils", "Brows", "Beak" } do
	local p = find(n); if p then motor(body, p, body.CFrame) end
end
for _, a in ARMS do
	a.m, a.base = {}, {}
	local prev = body
	for k = 1, 4 do
		local seg = find(("Tentacle%d_Seg%d"):format(a.i, k)) :: BasePart
		a.m[k] = motor(prev, seg, CFrame.new(W(a.joints[k])) * rot0)
		a.base[k] = a.m[k].C0
		local s = find(seg.Name .. "_Suckers")
		if s then motor(seg, s, seg.CFrame) end
		prev = seg
		if k == 4 then a.tip = seg end
	end
end
for _, d in model:GetDescendants() do
	if d:IsA("BasePart") and d ~= root then d.Anchored = false; d.CanCollide = false; d.Massless = true end
end

-- VFX: glowing eyes
local eyes = find("Eyes") :: BasePart
eyes.Material = Enum.Material.Neon
eyes.Color = Color3.fromRGB(255, 170, 40)
local eyeLight = Instance.new("PointLight")
eyeLight.Color = Color3.fromRGB(255, 140, 30); eyeLight.Range = math.clamp(8 * SCALE, 8, 60); eyeLight.Shadows = true
eyeLight.Parent = eyes

-- VFX: dark ink mist + droplets behind each tentacle tip (only while swimming)
local emitters = {}
for _, a in ARMS do
	local att = Instance.new("Attachment"); att.Name = "InkTrail"; att.Position = a.tipOff * SCALE; att.Parent = a.tip
	local m = Instance.new("ParticleEmitter")
	m.Name = "InkMist"
	m.Texture = "rbxasset://textures/particles/smoke_main.dds"
	m.Color = ColorSequence.new(Color3.fromRGB(8, 18, 24))
	m.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.15, 0.45), NumberSequenceKeypoint.new(1, 1) })
	m.Size = NumberSequence.new(0.4 * SCALE, 1.6 * SCALE)
	m.Lifetime = NumberRange.new(1.2, 2)
	m.Speed = NumberRange.new(0.2, 0.6); m.Drag = 2; m.SpreadAngle = Vector2.new(40, 40)
	m.RotSpeed = NumberRange.new(-40, 40); m.Rotation = NumberRange.new(0, 360)
	m.Rate = 0; m.Parent = att
	local d = Instance.new("ParticleEmitter")
	d.Name = "InkDroplets"
	d.Color = ColorSequence.new(Color3.fromRGB(12, 24, 30))
	d.Transparency = NumberSequence.new(0.1, 1)
	d.Size = NumberSequence.new(0.12 * SCALE, 0.04 * SCALE)
	d.Lifetime = NumberRange.new(0.8, 1.4)
	d.Speed = NumberRange.new(0.5 * SCALE, 1.5 * SCALE); d.SpreadAngle = Vector2.new(60, 60)
	d.Acceleration = Vector3.new(0, -4 * SCALE, 0); d.Drag = 0.8
	d.Rate = 0; d.Parent = att
	table.insert(emitters, { m = m, d = d })
end

local function smooth(x) x = math.clamp(x, 0, 1); return x * x * (3 - 2 * x) end
local function stroke(ph)
	ph = ph % 1
	if ph < 0.45 then return smooth(ph / 0.45) end
	if ph < 0.62 then return 1 - smooth((ph - 0.45) / 0.17) end
	return 0
end
local function lerp(a, b, w) return a + (b - a) * w end

model:SetAttribute("Anim", model:GetAttribute("Anim") or "Idle")
local t, w = 0, 0
RunService.Heartbeat:Connect(function(dt)
	t += dt
	w += (((model:GetAttribute("Anim") == "Swim") and 1 or 0) - w) * math.min(1, dt * 3)
	local ph = t / SWIM_PERIOD
	local power = math.max(0, math.sin(math.pi * math.clamp(((ph % 1) - 0.45) / 0.3, 0, 1)))

	local y  = lerp(0.25 * math.sin(t * 0.9), 0.08 * math.sin(ph * math.pi * 2), w)
	local z  = lerp(0, 0.3 * power, w)
	local rx = lerp(0.05 * math.sin(t * 0.7), 0.6, w)
	local ry = lerp(0.08 * math.sin(t * 0.3), 0, w)
	local rz = lerp(0.04 * math.sin(t * 0.55), 0.03 * math.sin(t * 0.8), w)
	bodyMotor.C0 = bodyC0 * CFrame.new(0, y * SCALE, z * SCALE) * CFrame.Angles(rx, ry, rz)

	for _, a in ARMS do
		local amp = a.hunter and { 0.1, 0.2, 0.3, 0.45 } or { 0.08, 0.16, 0.24, 0.34 }
		local sway = lerp(0.12 * math.sin(t * 0.5 + a.ph), 0, w)
		for k = 1, 4 do
			local idle = a.rest[k] + amp[k] * math.sin(t * 0.8 * a.sp - (k - 1) * 0.9 + a.ph)
			if k == 4 then idle += (a.hunter and 0.3 or 0.15) * math.sin(t * 0.35 + a.ph) end
			local f = stroke(ph - (k - 1) * 0.05)
			local swim
			if a.hunter then swim = ({ 0.25 + 0.6 * f, 0.1 + 0.3 * f, 0.1 + 0.3 * f, 0.2 + 0.35 * f })[k]
			else swim = ({ 0.3 + 0.9 * f, 0.05 + 0.3 * f, 0.1 + 0.35 * f, 0.15 + 0.45 * f })[k] end
			local delta = lerp(idle, swim, w) - a.rest[k]
			local r = CFrame.fromAxisAngle(a.axis, -delta)
			if k == 1 then r = CFrame.fromAxisAngle(Vector3.yAxis, sway) * r end
			a.m[k].C0 = a.base[k] * r
		end
	end

	local pulse = 0.6 + 0.35 * math.sin(t * 2.2) + 0.15 * math.sin(t * 6.3) + 0.5 * w * stroke(ph)
	eyeLight.Brightness = 1 + pulse * 3
	eyes.Color = Color3.fromRGB(255, 120 + 60 * math.clamp(pulse, 0, 1), 30)
	for _, e in emitters do
		e.m.Rate = (w > 0.05) and 14 * w or 0
		e.d.Rate = (w > 0.05) and 20 * w or 0
	end
end)
